package com.champlain.carrental.service;
import com.champlain.carrental.domain.*;import com.champlain.carrental.dto.*;import com.champlain.carrental.repository.*;import com.champlain.carrental.exception.*;import com.champlain.carrental.mapper.ApiMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.time.temporal.ChronoUnit;import java.math.BigDecimal;import java.util.*;
@Service @Transactional public class RentalService {
private final RentalRepository rentals;private final CarService cars;private final CustomerService customers;
public RentalService(RentalRepository rentals,CarService cars,CustomerService customers){this.rentals=rentals;this.cars=cars;this.customers=customers;}
private Rental get(Long id){return rentals.findById(id).orElseThrow(()->new NotFoundException("Rental "+id+" not found"));}
@Transactional(readOnly=true) public List<RentalResponseDTO> all(RentalStatus status){return (status==null?rentals.findAll():rentals.findByStatus(status)).stream().map(ApiMapper::rental).toList();}
@Transactional(readOnly=true) public RentalResponseDTO one(Long id){return ApiMapper.rental(get(id));}
private void dates(RentalRequestDTO d,boolean creation){if(!d.endDate().isAfter(d.startDate()))throw new IllegalArgumentException("End date must be after start date");if(creation&&d.startDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("Start date cannot be in the past");}
private BigDecimal price(Car c,RentalRequestDTO d){return c.dailyRate.multiply(BigDecimal.valueOf(ChronoUnit.DAYS.between(d.startDate(),d.endDate())));}
public RentalResponseDTO create(RentalRequestDTO d){dates(d,true);Car c=cars.getEntity(d.carId());Customer customer=customers.getEntity(d.customerId());if(c.status!=CarStatus.AVAILABLE)throw new ConflictException("Car is not available");Rental r=new Rental();r.car=c;r.customer=customer;r.startDate=d.startDate();r.endDate=d.endDate();r.totalPrice=price(c,d);r.status=RentalStatus.ACTIVE;c.status=CarStatus.RENTED;return ApiMapper.rental(rentals.save(r));}
public RentalResponseDTO update(Long id,RentalRequestDTO d){Rental r=get(id);if(r.status!=RentalStatus.ACTIVE)throw new ConflictException("Only active rentals can be updated");dates(d,false);Car c=cars.getEntity(d.carId());Customer customer=customers.getEntity(d.customerId());if(!r.car.id.equals(c.id)){if(c.status!=CarStatus.AVAILABLE)throw new ConflictException("New car is not available");r.car.status=CarStatus.AVAILABLE;c.status=CarStatus.RENTED;}r.car=c;r.customer=customer;r.startDate=d.startDate();r.endDate=d.endDate();r.totalPrice=price(c,d);return ApiMapper.rental(rentals.save(r));}
public RentalResponseDTO returned(Long id){Rental r=get(id);if(r.status!=RentalStatus.ACTIVE)throw new ConflictException("Rental is not active");r.returnDate=LocalDate.now();r.status=RentalStatus.COMPLETED;r.car.status=CarStatus.AVAILABLE;return ApiMapper.rental(r);}
public void delete(Long id){Rental r=get(id);if(r.status==RentalStatus.ACTIVE)throw new ConflictException("Return the car before deleting an active rental");rentals.delete(r);}
@Transactional(readOnly=true) public RentalWithDetailsResponseDTO details(Long id){Rental r=get(id);return new RentalWithDetailsResponseDTO(ApiMapper.rental(r),ApiMapper.car(r.car),ApiMapper.customer(r.customer));}
}